import{_ as s,C as n,o as e,c as i,a2 as a,b as d,w as r,a as l,E as c,a3 as u}from"./chunks/framework.O93z6AWZ.js";const A=JSON.parse('{"title":"Topic 2.7 — Fundus Image Quality Assessment (IQA)","description":"","frontmatter":{"title":"Topic 2.7 — Fundus Image Quality Assessment (IQA)"},"headers":[],"relativePath":"en/du_an/iqa_fundus.md","filePath":"en/du_an/iqa_fundus.md"}'),h={name:"en/du_an/iqa_fundus.md"};function g(p,t,m,f,b,y){const o=n("Mermaid");return e(),i("div",null,[t[1]||(t[1]=a('<h1 id="topic-2-7-automated-fundus-image-quality-assessment-iqa" tabindex="-1">Topic 2.7: Automated Fundus Image Quality Assessment (IQA) <a class="header-anchor" href="#topic-2-7-automated-fundus-image-quality-assessment-iqa" aria-label="Permalink to &quot;Topic 2.7: Automated Fundus Image Quality Assessment (IQA)&quot;">​</a></h1><p><strong>Topic group:</strong> 2. Medical Imaging (Fundus/Dermatology) · <strong>Status:</strong> ✅ Starter documentation complete</p><div class="tip custom-block"><p class="custom-block-title">📥 Full documentation on GitHub</p><p>Raw data and detailed source code are kept <strong>Private</strong> on the department&#39;s GitHub repository (so students complete the work themselves). This topic is the <strong>quality gate</strong> standing before the other diagnostic topics in the group (<a href="/hmyt-book/en/du_an/day_mat">2.2 DR</a>, <a href="/hmyt-book/en/du_an/glocom">2.3 Glaucoma</a>, <a href="/hmyt-book/en/du_an/amd">2.4 AMD</a>, <a href="/hmyt-book/en/du_an/erm">2.5 ERM</a>) — blurry/dark/noisy images must be rejected before being fed into a disease-diagnosis model.</p></div><p>Read the <strong><a href="/hmyt-book/en/course_project">Management Framework &amp; Rubric</a></strong> first.</p><hr><h2 id="_1-problem-statement" tabindex="-1">1. Problem statement <a class="header-anchor" href="#_1-problem-statement" aria-label="Permalink to &quot;1. Problem statement&quot;">​</a></h2><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Research question</strong></td><td>Automatically classify fundus image quality (gradable/ungradable for diagnosis) using deep learning, with explainability (XAI) for why an image is rejected</td></tr><tr><td><strong>Input (X)</strong></td><td>Fundus photograph</td></tr><tr><td><strong>Output (Y)</strong></td><td>Binary (gradable/ungradable) or 3-class (Good/Usable/Reject per the EyeQ standard)</td></tr><tr><td><strong>Suggested dataset</strong></td><td><a href="https://github.com/HzFu/EyeQ" target="_blank" rel="noreferrer">EyeQ</a> (based on EyePACS/Kaggle, 28,792 images, 3 quality levels) — or a smaller subset if resources are limited</td></tr><tr><td><strong>Mandatory requirement</strong></td><td>Must explain <strong>why</strong> an image is rejected (blur/dark/noise/occlusion) — not just output a plain binary label</td></tr></tbody></table><h2 id="_2-starter-literature-9-include-1-context-—-meets-the-≥10-paper-rubric-milestone-1-requirement" tabindex="-1">2. Starter literature (9 INCLUDE + 1 CONTEXT — meets the ≥10-paper Rubric Milestone 1 requirement) <a class="header-anchor" href="#_2-starter-literature-9-include-1-context-—-meets-the-≥10-paper-rubric-milestone-1-requirement" aria-label="Permalink to &quot;2. Starter literature (9 INCLUDE + 1 CONTEXT — meets the ≥10-paper Rubric Milestone 1 requirement)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Citekey</th><th style="text-align:center;">Year</th><th>DOI</th><th>Summary</th></tr></thead><tbody><tr><td><code>fu2019evaluation</code> <em>(CONTEXT)</em></td><td style="text-align:center;">2019</td><td><a href="https://doi.org/10.1007/978-3-030-32239-7_6" target="_blank" rel="noreferrer">10.1007/978-3-030-32239-7_6</a></td><td>The foundational EyeQ dataset (28,792 images, 3 levels) + MCF-Net (Multiple Color-space Fusion Network)</td></tr><tr><td><code>khalid2024fgrnet</code></td><td style="text-align:center;">2024</td><td><a href="https://doi.org/10.1016/j.eswa.2023.121644" target="_blank" rel="noreferrer">10.1016/j.eswa.2023.121644</a></td><td><strong>FGR-Net</strong> — Autoencoder + classifier, accuracy 89%/F1 87%, explainable (focuses on fovea/optic disc/vessels)</td></tr><tr><td><code>shi2022assessment</code></td><td style="text-align:center;">2022</td><td><a href="https://doi.org/10.1038/s41598-022-13919-2" target="_blank" rel="noreferrer">10.1038/s41598-022-13919-2</a></td><td>ResNet50 transfer learning, sensitivity/specificity/accuracy 98.0%/99.1%/98.6% (2,434 images); separates poor quality <strong>due to eye disease</strong> from poor quality <strong>due to acquisition artefacts</strong>; external validation AUC 0.997 (overall quality), 0.915 (two types of poor quality)</td></tr><tr><td><code>coyner2019automated</code></td><td style="text-align:center;">2019</td><td><a href="https://doi.org/10.1016/j.oret.2019.01.015" target="_blank" rel="noreferrer">10.1016/j.oret.2019.01.015</a></td><td>CNN on 6,139 <strong>infant</strong> images (Retinopathy of Prematurity), AUC 0.965 on the test set; quality ranking Spearman 0.90 against experts (30 images)</td></tr><tr><td><code>abramovich2023fundusqnet</code></td><td style="text-align:center;">2023</td><td><a href="https://doi.org/10.1016/j.cmpb.2023.107522" target="_blank" rel="noreferrer">10.1016/j.cmpb.2023.107522</a></td><td><strong>Regression approach</strong> — continuous 1-10 quality scale (Inception-V3), MAE 0.61 (95% CI 0.54–0.68); 99% accuracy when used as a binary classifier on DRIMDB (external test)</td></tr><tr><td><code>perez2020lightweight</code></td><td style="text-align:center;">2020</td><td><a href="https://doi.org/10.1117/12.2547126" target="_blank" rel="noreferrer">10.1117/12.2547126</a></td><td>A lightweight model deployed on <strong>smartphone</strong>, accuracy 0.911 (binary)/0.856 (3-class)</td></tr><tr><td><code>wang2025infant</code></td><td style="text-align:center;">2025</td><td><a href="https://doi.org/10.1038/s41598-025-10859-5" target="_blank" rel="noreferrer">10.1038/s41598-025-10859-5</a></td><td>The DLIF-QFS system detects <strong>specific operational error types</strong> on 13,372 infant images; external validation AUC: Poor 0.802 · <strong>Adequate 0.691</strong> · Excellent 0.926</td></tr><tr><td><code>khalid2024vista</code></td><td style="text-align:center;">2024</td><td><a href="https://doi.org/10.1007/s00521-024-10174-6" target="_blank" rel="noreferrer">10.1007/s00521-024-10174-6</a></td><td><strong>VISTA</strong> — extends FGR-Net, processes images at original resolution (no downsampling), accuracy 0.91/F1 0.89</td></tr><tr><td><code>oh2025uwf</code></td><td style="text-align:center;">2025</td><td><a href="https://doi.org/10.1136/bmjopen-2025-100058" target="_blank" rel="noreferrer">10.1136/bmjopen-2025-100058</a></td><td><strong>Ultra-widefield</strong> imaging (a different modality) — 4 separate scoring criteria, EfficientNet-B3; mean weighted kappa with graders 0.731 (inter-grader only 0.603)</td></tr><tr><td><code>guo2024refined</code></td><td style="text-align:center;">2024</td><td><a href="https://doi.org/10.1177/20552076231207582" target="_blank" rel="noreferrer">10.1177/20552076231207582</a></td><td>Assesses <strong>multiple component criteria</strong> (Location, Clarity, Artifact × 3 levels) instead of one overall label; 55,931 images; overall quality accuracy 88.15% internal, 86.63% external</td></tr></tbody></table><div class="warning custom-block"><p class="custom-block-title">Beware overly perfect metrics — <code>shi2022assessment</code></p><p>98.6% accuracy on only 2,434 images (10-fold CV). The paper <strong>does</strong> include external validation (AUC 0.997 for overall quality, 0.915 for separating the two types of poor quality), but the size and source of the external set must be read in the full text before comparing. Reasonable as a &quot;target to beat&quot;, but don&#39;t treat it as an easy bar — the team should still run its own external validation.</p></div><div class="warning custom-block"><p class="custom-block-title">Domain gap — <code>coyner2019automated</code></p><p>This paper assesses image quality in <strong>infants</strong> (Retinopathy of Prematurity) — the population, imaging device, and image characteristics differ substantially from the adult diabetic/AMD fundus images used in the group&#39;s other topics. Useful for learning the technique, but don&#39;t expect the numbers to transfer directly to an adult dataset.</p></div><div class="warning custom-block"><p class="custom-block-title">Zero-Hallucination in practice — <code>guo2024refined</code></p><p>The figures in the table above come from the <strong>abstract</strong>. Architecture details, inference speed and how the three criteria were labelled are only in the full text — a team using this paper must read the full text for real numbers, not infer them from the abstract or from secondary sources.</p></div><h2 id="_3-why-this-topic-differs-from-2-2–2-6" tabindex="-1">3. Why this topic differs from 2.2–2.6 <a class="header-anchor" href="#_3-why-this-topic-differs-from-2-2–2-6" aria-label="Permalink to &quot;3. Why this topic differs from 2.2–2.6&quot;">​</a></h2><p>Topics 2.2 (DR), 2.3 (Glaucoma), 2.4 (AMD), 2.5 (ERM), 2.6 (Multi-disease Edge AI) all assume <strong>the input image already meets diagnostic quality</strong>. This topic solves the step <strong>before that</strong>: is the image good enough to feed into those models? This is exactly the problem the <strong>QualityAI</strong> module in the case study <em>&quot;CS-4: Edge AI Device Control Software&quot;</em> on <a href="https://fossbk-spec.github.io/ktpmud-book/do_an_mon_hoc" target="_blank" rel="noreferrer">ktpmud-book</a> must solve at the software layer — but there, for real-world deployment safety reasons, blocking bad images must use a <strong>deterministic (rule-based) threshold</strong>, not a deep-learning model deciding on its own. This <strong>research</strong> topic (for HMYT) is the opposite — the goal is to build and evaluate an actual <strong>ML model</strong> for the quality-classification problem, not to replace that rule-based safety gate.</p><h2 id="_4-7-stage-workflow" tabindex="-1">4. 7-stage workflow <a class="header-anchor" href="#_4-7-stage-workflow" aria-label="Permalink to &quot;4. 7-stage workflow&quot;">​</a></h2>',15)),(e(),d(u,null,{default:r(()=>[c(o,{id:"mermaid-259",class:"mermaid",graph:"flowchart%20LR%0A%20%20%20%20subgraph%20GD1%5B%22gd1%20(W1-2)%22%5D%0A%20%20%20%20%20%20%20%20A1%5BRead%2010%20starter%20papers%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20GD2%5B%22gd2%20(W2-3)%22%5D%0A%20%20%20%20%20%20%20%20B1%5BDownload%20EyeQ%2Fsubset%5D%20--%3E%20B2%5BEDA%20on%203-level%20quality%20distribution%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20GD3%5B%22gd3%20(W4-5)%22%5D%0A%20%20%20%20%20%20%20%20C1%5BNormalize%2Faugment%20images%5D%20--%3E%20C2%5BPatient%2Feye-level%20split%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20GD4%5B%22gd4%20(W5-6)%22%5D%0A%20%20%20%20%20%20%20%20D1%5BSimple%20baseline%20CNN%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20GD5%5B%22gd5%20(W7-10)%22%5D%0A%20%20%20%20%20%20%20%20E1%5BProposed%20architecture%3Cbr%3Econsider%20autoencoder%2Bclassifier%20like%20FGR-Net%5D%20--%3E%20E2%5BAblation%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20GD6%5B%22gd6%20(W10-12)%22%5D%0A%20%20%20%20%20%20%20%20F1%5BMulti-metric%20%2B%20Bootstrap%2095%25%20CI%5D%20--%3E%20F2%5BGrad-CAM%20explaining%20rejection%20reasons%5D%0A%20%20%20%20end%0A%20%20%20%20subgraph%20GD7%5B%22gd7%20(W12-15)%22%5D%0A%20%20%20%20%20%20%20%20G1%5BPaper%20%2B%20README%20%2B%20Slides%5D%0A%20%20%20%20end%0A%20%20%20%20GD1%20--%3E%20GD2%20--%3E%20GD3%20--%3E%20GD4%20--%3E%20GD5%20--%3E%20GD6%20--%3E%20GD7%0A"})]),fallback:r(()=>[...t[0]||(t[0]=[l(" Loading... ",-1)])]),_:1})),t[2]||(t[2]=a('<p><strong>Specific note:</strong> If choosing the 3-class setup (Good/Usable/Reject) instead of binary, consider Ordinal Classification, or at minimum report a full 3×3 confusion matrix — confusing &quot;Usable&quot; with &quot;Reject&quot; is more dangerous than confusing &quot;Good&quot; with &quot;Usable&quot;.</p><h2 id="_5-15-week-timeline" tabindex="-1">5. 15-week timeline <a class="header-anchor" href="#_5-15-week-timeline" aria-label="Permalink to &quot;5. 15-week timeline&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Week</th><th>Main work</th><th>Milestone</th></tr></thead><tbody><tr><td style="text-align:center;">1-3</td><td>≥10-paper literature review, download dataset, EDA</td><td><strong>M1 (15%) — Week 3</strong></td></tr><tr><td style="text-align:center;">4-6</td><td>Patient/eye-level split, augmentation, baseline</td><td><strong>M2 (20%) — Week 6</strong></td></tr><tr><td style="text-align:center;">7-10</td><td>Proposed architecture, ablation</td><td><strong>M3 (25%) — Week 10</strong></td></tr><tr><td style="text-align:center;">11-12</td><td>Multi-metric evaluation, Grad-CAM explanation</td><td><strong>M4 (15%) — Week 12</strong></td></tr><tr><td style="text-align:center;">13-15</td><td>Paper, repo, slides, Q&amp;A</td><td><strong>Final (25%) — Week 15</strong></td></tr></tbody></table><h2 id="_6-advanced-research-track-optional" tabindex="-1">6. Advanced research track (optional) <a class="header-anchor" href="#_6-advanced-research-track-optional" aria-label="Permalink to &quot;6. Advanced research track (optional)&quot;">​</a></h2><p>For teams that have completed the main scope (sections 1–5) and want to go further, or for postgraduate research. The full proposal is an internal document of the research group (provided by the lecturer when a team registers for this track).</p><p><strong>Gaps in the literature (from the 10 papers in section 2):</strong></p><ul><li><strong>Ambiguous middle class:</strong> the Adequate class reaches only AUC 0.691 in external validation (<code>wang2025infant</code>); inter-grader agreement on ultra-widefield images is only 0.603 (<code>oh2025uwf</code>). The reference labels themselves are uncertain.</li><li><strong>Domain shift:</strong> each paper uses only one or a few devices or populations (infant RetCam, Optos ultra-widefield, adult 45° images).</li><li><strong>Explanations that are anatomically faithful and fast:</strong> RISE/occlusion are slow; Grad-CAM can focus on border regions (<code>khalid2024fgrnet</code>, <code>khalid2024vista</code>).</li><li><strong>Several acquisition errors in one image</strong> (<code>wang2025infant</code>).</li></ul><p><strong>Three research questions sized for a course project</strong> (each is a measurable hypothesis; thresholds must be fixed in advance):</p><table tabindex="0"><thead><tr><th>RQ</th><th>Hypothesis</th><th>Measures</th></tr></thead><tbody><tr><td>RQ1 — Multi-task: quality level + acquisition-error detection</td><td>QWK does not drop by more than a pre-specified margin compared with a quality-only model; latency &lt; 50 ms/image <strong>on a named device</strong></td><td>QWK (95% CI), per-error AUC, median and p95 latency</td></tr><tr><td>RQ2 — Domain adaptation without new labels</td><td>The QWK gap between the training source and the external source shrinks compared with a non-adapted model</td><td>QWK and macro-F1 per source, patient-level bootstrap</td></tr><tr><td>RQ3 — Concept-based explanations vs Grad-CAM</td><td>Explanation maps concentrate more on the optic disc/macula/vessels, at ≤ 2× compute</td><td>Share of map energy inside hand-annotated anatomical regions on a subset; explanation time</td></tr></tbody></table><p>Whether triaging acquisition errors vs disease reduces wrong referrals is a <strong>clinical impact</strong> question that needs a deployment study under DECIDE-AI — <strong>out of scope</strong> for the course project.</p><div class="danger custom-block"><p class="custom-block-title">Required for the advanced track</p><ul><li>Split data <strong>by patient</strong> (EyeQ/EyePACS contain both eyes of the same person).</li><li>Report who labelled the images and their agreement; analyse the middle class separately.</li><li>External validation on at least one image source from a different device or population.</li><li>No public dataset among the 10 papers has acquisition-error labels: state how labels are obtained (manual labelling of a subset, controlled simulation of errors) and the limits of that approach.</li><li>Check against the checklist in the <a href="/hmyt-book/en/phu_luc_fair_tripod_probast">Appendix: FAIR, TRIPOD+AI, PROBAST+AI</a> (section 7).</li></ul></div><div class="warning custom-block"><p class="custom-block-title">Zero-Hallucination</p><p>Every citation must match a real key in <code>.bib</code> with a DOI verified via the Crossref API.</p></div>',12))])}const _=s(h,[["render",g]]);export{A as __pageData,_ as default};
